def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    opp_d = 0
    my_d = 0
    cD = 0
    dD = 0
    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1
        if i > 0 and history[i - 1][0] == 'D':
            if b == 'C':
                cD += 1
            else:
                dD += 1

    last_opp = history[-1][1]
    prev_my = history[-2][0]

    if opp_d == 0:
        if my_d == 0:
            return 'D' if n >= 10 else 'C'
        if prev_my == 'D':
            return 'D'
        return 'C'

    opp_c = n - opp_d
    opp_c_rate = opp_c / float(n)
    respD = cD + dD
    if respD > 0:
        forgive_rate = cD / float(respD)
    else:
        forgive_rate = opp_c_rate

    r = 10 if n >= 10 else n
    recent = history[-r:]
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    recent_my_d = sum(1 for m, _ in recent if m == 'D')

    if opp_c == 0:
        return 'D'

    my_streak = 0
    j = n - 1
    while j >= 0 and history[j][0] == 'D':
        my_streak += 1
        j -= 1

    if recent_opp_d >= 8 or (recent_opp_d >= 6 and opp_c_rate < 0.55):
        return 'D'

    if n >= 95:
        if last_opp == 'C' and prev_my == 'D':
            if opp_c_rate >= 0.9 and forgive_rate >= 0.85 and my_streak <= 4:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if prev_my == 'D' and opp_c_rate >= 0.55:
            return 'C'
        streak = 1
        i = n - 2
        while i >= 0 and history[i][1] == 'D':
            streak += 1
            i -= 1
        if opp_c_rate >= 0.8 and recent_opp_d <= 2 and streak <= 2 and recent_my_d <= 3 and forgive_rate >= 0.8 and rng.random() < 0.35:
            return 'C'
        if opp_c_rate >= 0.75 and recent_opp_d <= 1 and forgive_rate >= 0.7 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if prev_my == 'D':
        if opp_c_rate >= 0.95 and (forgive_rate >= 0.9 or my_streak <= 1):
            return 'D'
        if opp_c_rate >= 0.9 and forgive_rate >= 0.85:
            if my_streak <= 5:
                return 'D'
            return 'D' if rng.random() < 0.3 else 'C'
        if opp_c_rate >= 0.7 and forgive_rate >= 0.75 and my_streak <= 3:
            return 'D' if rng.random() < 0.55 else 'C'
        if opp_c_rate >= 0.85 and forgive_rate >= 0.9 and my_streak <= 2 and rng.random() < 0.6:
            return 'D'
        return 'C'

    return 'C'
